column7:
{
  "non_functional_requirements": [
    {"id": "NFR1", "description": "System musi zapewniać czas odpowiedzi na zapytanie o dostępność terminów nie przekraczający 2 sekund przy 1000 równoczesnych użytkownikach."},
    {"id": "NFR2", "description": "Wszystkie dane osobowe oraz dane o wizytach muszą być szyfrowane zgodnie ze standardem AES-256 oraz spełniać wymogi RODO."},
    {"id": "NFR3", "description": "System musi charakteryzować się dostępnością na poziomie 99,9% w skali miesiąca."},
    {"id": "NFR4", "description": "Interfejs użytkownika musi być w pełni responsywny (RWD), zapewniając poprawną obsługę na urządzeniach mobilnych i desktopowych."},
    {"id": "NFR5", "description": "System musi automatycznie wylogować użytkownika po 15 minutach nieaktywności w celu zapewnienia bezpieczeństwa sesji."}
  ],
  "user_stories": [
    {"id": "US1", "description": "Jako Użytkownik chcę wyszukać specjalistę po nazwisku lub specjalizacji, aby szybko znaleźć odpowiednią osobę na wizytę."},
    {"id": "US2", "description": "Jako Użytkownik chcę otrzymać potwierdzenie rezerwacji na e-mail, aby mieć pewność, że proces zakończył się sukcesem."},
    {"id": "US3", "description": "Jako Specjalista chcę blokować wybrane dni w grafiku (np. urlop), aby pacjenci nie mogli zapisywać się w czasie mojej nieobecności."},
    {"id": "US4", "description": "Jako Specjalista chcę widzieć powód wizyty podany przez pacjenta, aby móc lepiej przygotować się do konsultacji."},
    {"id": "US5", "description": "Jako Administrator chcę generować raporty miesięczne dotyczące liczby zrealizowanych wizyt, aby analizować obłożenie systemu."}
  ]
}

