column7:
{
  "acceptance_criteria": [
    {
      "id": "AC1",
      "given": "Użytkownik znajduje się na stronie wyszukiwania specjalistów",
      "when": "Użytkownik wprowadzi nazwisko lub specjalizację w pole wyszukiwania i zatwierdzi wybór",
      "then": "System wyświetla listę specjalistów pasujących do wpisanych kryteriów"
    },
    {
      "id": "AC2",
      "given": "Użytkownik pomyślnie przeszedł proces rezerwacji wizyty",
      "when": "Rezerwacja zostanie zatwierdzona w bazie danych",
      "then": "System wysyła wiadomość e-mail z potwierdzeniem terminu na adres użytkownika"
    },
    {
      "id": "AC3",
      "given": "Specjalista jest zalogowany i widzi swój kalendarz pracy",
      "when": "Specjalista zaznaczy wybrany zakres dni jako niedostępny i zapisze zmiany",
      "then": "System blokuje możliwość zapisu pacjentów na wizyty w wyznaczonym terminie"
    },
    {
      "id": "AC4",
      "given": "Specjalista przegląda szczegóły nadchodzącej wizyty w swoim panelu",
      "when": "Specjalista otworzy kartę konkretnej wizyty",
      "then": "System wyświetla pole z opisem powodu wizyty wprowadzonym przez pacjenta"
    },
    {
      "id": "AC5",
      "given": "Administrator jest zalogowany w module analitycznym",
      "when": "Administrator wybierze miesiąc i wygeneruje raport obłożenia",
      "then": "System tworzy zestawienie zawierające sumaryczną liczbę zrealizowanych wizyt w wybranym okresie"
    }
  ]
}

