column7:
{
  "roles": [
    {
      "name": "Użytkownik",
      "permissions": [
        "przeglądanie dostępnych terminów",
        "dokonywanie rezerwacji wizyt",
        "anulowanie własnych rezerwacji"
      ]
    },
    {
      "name": "Specjalista",
      "permissions": [
        "zarządzanie własnym grafikiem",
        "przeglądanie listy zapisanych wizyt",
        "anulowanie wizyt klientów"
      ]
    },
    {
      "name": "Administrator",
      "permissions": [
        "zarządzanie kontami użytkowników i specjalistów",
        "konfiguracja globalnych ustawień systemu"
      ]
    }
  ],
  "functional_requirements": [
    {
      "id": "FR1",
      "description": "System musi umożliwiać użytkownikom wyszukiwanie specjalistów oraz przeglądanie ich wolnych terminów w czasie rzeczywistym."
    },
    {
      "id": "FR2",
      "description": "System musi umożliwiać użytkownikom zarezerwowanie wybranego terminu po uprzednim uwierzytelnieniu."
    },
    {
      "id": "FR3",
      "description": "System musi umożliwiać użytkownikom oraz specjalistom anulowanie istniejącej rezerwacji zgodnie z polityką anulowań."
    },
    {
      "id": "FR4",
      "description": "System musi umożliwiać specjalistom definiowanie, edytowanie i usuwanie bloków czasowych w ich grafiku dostępności."
    },
    {
      "id": "FR5",
      "description": "System musi automatycznie blokować termin w momencie rozpoczęcia procesu rezerwacji, aby zapobiec konfliktom (double-booking)."
    },
    {
      "id": "FR6",
      "description": "System musi wymuszać kontrolę dostępu opartą na rolach (RBAC) dla wszystkich operacji na danych."
    }
  ]
}

