column7:
{
  "non_functional_requirements": [
    {"id": "NFR1", "description": "System musi zapewniać czas odpowiedzi na zapytanie o dostępność terminów poniżej 2 sekund przy 500 równoczesnych użytkownikach."},
    {"id": "NFR2", "description": "System musi być dostępny na poziomie 99,9% w skali roku, z wyłączeniem planowanych przerw konserwacyjnych."},
    {"id": "NFR3", "description": "Wszystkie dane przesyłane między klientem a serwerem muszą być szyfrowane przy użyciu protokołu TLS 1.3."},
    {"id": "NFR4", "description": "Interfejs użytkownika musi być w pełni responsywny (RWD) i zapewniać poprawność działania na urządzeniach mobilnych i desktopowych."},
    {"id": "NFR5", "description": "Hasła użytkowników muszą być przechowywane w bazie danych w formie zahaszowanej przy użyciu silnego algorytmu, np. Argon2 lub bcrypt."}
  ],
  "user_stories": [
    {"id": "US1", "description": "Jako Użytkownik chcę wyszukiwać specjalistów według ich specjalizacji, aby szybko znaleźć odpowiednią pomoc."},
    {"id": "US2", "description": "Jako Użytkownik chcę otrzymać e-mailowe potwierdzenie rezerwacji, aby mieć pewność, że termin został zapisany."},
    {"id": "US3", "description": "Jako Specjalista chcę oznaczać wybrane dni jako wolne od pracy, aby pacjenci nie mogli zapisywać się w czasie mojego urlopu."},
    {"id": "US4", "description": "Jako Specjalista chcę widzieć listę pacjentów zapisanych na dany dzień, aby móc lepiej zaplanować swój czas pracy."},
    {"id": "US5", "description": "Jako Administrator chcę mieć możliwość resetowania haseł użytkowników, aby pomóc im w przypadku utraty dostępu do konta."}
  ]
}

column6:
User stories: [{"id": "US1", "description": "Jako Użytkownik chcę wyszukiwać specjalistów według ich specjalizacji, aby szybko znaleźć odpowiednią pomoc."}, {"id": "US2", "description": "Jako Użytkownik chcę otrzymać e-mailowe potwierdzenie rezerwacji, aby mieć pewność, że termin został zapisany."}, {"id": "US3", "description": "Jako Specjalista chcę oznaczać wybrane dni jako wolne od pracy, aby pacjenci nie mogli zapisywać się w czasie mojego urlopu."}, {"id": "US4", "description": "Jako Specjalista chcę widzieć listę pacjentów zapisanych na dany dzień, aby móc lepiej zaplanować swój czas pracy."}, {"id": "US5", "description": "Jako Administrator chcę mieć możliwość resetowania haseł użytkowników, aby pomóc im w przypadku utraty dostępu do konta."}]

