{
  "acceptance_criteria": [
    {
      "id": "AC1",
      "given": "Użytkownik znajduje się na stronie wyszukiwania specjalistów",
      "when": "Użytkownik wybierze określoną specjalizację z listy i kliknie przycisk szukaj",
      "then": "System wyświetla listę specjalistów posiadających wybraną specjalizację"
    },
    {
      "id": "AC2",
      "given": "Użytkownik pomyślnie ukończył proces rezerwacji terminu wizyty",
      "when": "Rezerwacja zostanie poprawnie zapisana w bazie danych",
      "then": "System wysyła automatyczną wiadomość e-mail z potwierdzeniem szczegółów wizyty na adres użytkownika"
    },
    {
      "id": "AC3",
      "given": "Specjalista jest zalogowany i otworzył swój kalendarz pracy",
      "when": "Specjalista zaznaczy wybrane daty jako wolne i zapisze zmiany",
      "then": "System blokuje możliwość rezerwacji terminów przez pacjentów w zaznaczonych dniach"
    },
    {
      "id": "AC4",
      "given": "Specjalista jest zalogowany w systemie",
      "when": "Specjalista wybierze konkretną datę z widoku harmonogramu",
      "then": "System wyświetla chronologiczną listę pacjentów zapisanych na wizyty w wybranym dniu"
    },
    {
      "id": "AC5",
      "given": "Administrator jest zalogowany w panelu zarządzania użytkownikami",
      "when": "Administrator wybierze opcję resetowania hasła dla wskazanego konta użytkownika",
      "then": "System generuje i wysyła link do ustawienia nowego hasła na adres e-mail przypisany do konta użytkownika"
    }
  ]
